#include <cstddef>
#include <utility>

class Buffer {
public:
    explicit Buffer(std::size_t size)
        : data_(new double[size]{}), size_(size) {}

    ~Buffer() {
        delete[] data_;  // delete[] on nullptr is well-defined
    }

    Buffer(const Buffer&) = delete;
    Buffer& operator=(const Buffer&) = delete;

    Buffer(Buffer&& other) noexcept
        : data_(std::exchange(other.data_, nullptr)),
          size_(std::exchange(other.size_, 0)) {}

    Buffer& operator=(Buffer&& other) noexcept {
        // Without this, `buffer = std::move(buffer)` would delete the
        // allocation and then try to take it from the object just emptied.
        if (this != &other) {
            delete[] data_;  // dispose of what we already own, or we leak
            data_ = std::exchange(other.data_, nullptr);
            size_ = std::exchange(other.size_, 0);
        }
        return *this;
    }

    bool empty() const { return size_ == 0; }

private:
    double* data_;
    std::size_t size_;
};

#include <unistd.h>

#include <utility>

class Socket {
public:
    explicit Socket(int fd) : fd_(fd) {}

    ~Socket() {
        if (fd_ >= 0) {
            ::close(fd_);
        }
    }

    Socket(const Socket&) = delete;
    Socket& operator=(const Socket&) = delete;

    // A defaulted move would perform a memberwise move of an int -- which is
    // just a copy. Both objects would then hold the same descriptor and both
    // destructors would close it. A direct resource owner must write the
    // transfer itself; only once ownership lives in a suitable member type
    // can the enclosing class default its moves.
    Socket(Socket&& other) noexcept : fd_(std::exchange(other.fd_, -1)) {}

    Socket& operator=(Socket&& other) noexcept {
        if (this != &other) {
            if (fd_ >= 0) {
                ::close(fd_);
            }
            fd_ = std::exchange(other.fd_, -1);
        }
        return *this;
    }

private:
    int fd_;
};

void consume(Socket socket) {
    (void)socket;  // socket now owns the connection
}

int open_connection();

void hand_off() {
    Socket connection{open_connection()};
    consume(std::move(connection));  // ownership enters consume
}

