#include <iostream>

struct Trace {
    Trace() = default;
    Trace(const Trace&) { std::cout << "member copy\n"; }
    Trace(Trace&&) noexcept { std::cout << "member move\n"; }
};

// The bug: a user-declared destructor suppresses the implicit move
// constructor and move assignment. `Widget b = std::move(a);` then finds the
// generated *copy* constructor, whose const Widget& parameter binds happily to
// an xvalue -- so it compiles, copies, and warns about nothing.

// Fix 1, preferred: the type manages no resource directly, so declare none of
// the five. Copying, moving, destruction and the conditional noexcept
// specifications are all generated correctly and stay correct as members
// change.
struct WidgetZero {
    Trace trace;
};

// Fix 2: the destructor is genuinely required, so state every operation.
struct WidgetExplicit {
    Trace trace;

    WidgetExplicit() = default;
    WidgetExplicit(const WidgetExplicit&) = default;
    WidgetExplicit& operator=(const WidgetExplicit&) = default;
    WidgetExplicit(WidgetExplicit&&) noexcept = default;
    WidgetExplicit& operator=(WidgetExplicit&&) noexcept = default;

    ~WidgetExplicit() { std::cout << "destroy\n"; }
};

#include <string>
#include <utility>

struct Order {
    std::string symbol;
};

// Guaranteed elision since C++17: a prvalue of the result type is constructed
// directly in the caller's result object. This is a language rule, so -O0 does
// not restore a move -- and it works even for a type with no copy or move
// constructor at all.
Order make_prvalue() {
    return Order{"EURUSD"};
}

// NRVO: the compiler is permitted to construct `order` directly in the return
// destination and production compilers usually do. If it does not, the return
// expression is move-eligible and the move constructor runs. Do NOT write
// `return std::move(order);` -- that discards the NRVO case to guarantee the
// worse one.
Order make_local() {
    Order order{"USDJPY"};
    return order;
}

// A by-value parameter lives in storage established for the call, so it can
// never use NRVO. This is an implicit move, guaranteed.
Order return_parameter(Order order) {
    return order;
}

// A subobject cannot use NRVO either, and a bare `return order.symbol;` copies.
// The explicit std::move is warranted here precisely because there is no
// elision to lose.
std::string return_member() {
    Order order{"GBPUSD"};
    return std::move(order.symbol);
}

#include <iostream>
#include <vector>

struct MayThrowMove {
    MayThrowMove() = default;
    MayThrowMove(const MayThrowMove&) { std::cout << "copy-ctor\n"; }
    MayThrowMove(MayThrowMove&&) { std::cout << "move-ctor\n"; }
};

struct NoexceptMove {
    NoexceptMove() = default;
    NoexceptMove(const NoexceptMove&) { std::cout << "copy-ctor\n"; }
    NoexceptMove(NoexceptMove&&) noexcept { std::cout << "move-ctor\n"; }
};

int main() {
    // reserve(2) makes the third insertion require new storage, without
    // claiming anything about the growth factor. The library relocates the two
    // existing elements with std::move_if_noexcept: a potentially throwing
    // move with a copy available yields a const lvalue, which selects copying
    // so the original range survives a throw intact.
    std::vector<MayThrowMove> cautious;
    cautious.reserve(2);
    cautious.emplace_back();
    cautious.emplace_back();
    cautious.emplace_back();  // copy-ctor twice

    std::vector<NoexceptMove> fast;
    fast.reserve(2);
    fast.emplace_back();
    fast.emplace_back();
    fast.emplace_back();      // move-ctor twice
}

#include <iostream>
#include <string>
#include <utility>

void reuse_after_move() {
    std::string symbol = "EURUSD";
    std::string destination = std::move(symbol);

    std::cout << destination << '\n';  // allowed: prints EURUSD

    // The standard guarantees a moved-from library object is valid but holds
    // an unspecified value. Its invariants hold; which ordinary value it
    // contains is simply not specified.

    // Reading it: allowed, but the output is unspecified.
    std::cout << symbol.size() << '\n';

    // Calling an operation with no preconditions: allowed.
    symbol.clear();

    // NOT allowed to rely on: `assert(symbol.empty());`. Implementations
    // commonly do leave a moved-from string empty, which is exactly what makes
    // depending on it a portability trap rather than an obvious mistake.

    // Assigning a fresh value: allowed, and this is what makes the object
    // useful again -- every later read is now well defined.
    symbol = "USDJPY";
    std::cout << symbol << '\n';  // prints USDJPY
}
